const { withAndroidStyles } = require('expo/config-plugins');

/**
 * Tells the Android 12+ system splash how long its animated icon (the AnimatedVectorDrawable in
 * assets/splash, generated by scripts/build-brand-assets.mjs) runs. The platform caps it at 1000 ms.
 *
 * `expo-splash-screen` has no prop for this, and it rewrites the whole `Theme.App.SplashScreen` style on
 * every prebuild, so this plugin adds one item to what it produced. It must therefore be listed BEFORE
 * 'expo-splash-screen' in app.config.ts: Expo runs a later plugin's mod first, and this one has to run after.
 *
 * Options: { duration: ms (default 1000) }
 */
const STYLE = 'Theme.App.SplashScreen';

module.exports = function withSplashAnimation(config, { duration = 1000 } = {}) {
  return withAndroidStyles(config, (cfg) => {
    const style = cfg.modResults.resources.style?.find((s) => s.$.name === STYLE);
    if (!style) throw new Error(`with-splash-animation: ${STYLE} not found — list this plugin before expo-splash-screen`);
    const name = 'windowSplashScreenAnimationDuration';
    const existing = style.item.find((i) => i.$.name === name);
    if (existing) existing._ = String(duration);
    else style.item.push({ $: { name }, _: String(duration) });
    return cfg;
  });
};
